glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform SlicedBorderUniform {
  vec4 borderColor;
  vec4 targetInfo;
  vec4 sourceInfo;
  vec4 sliceInsets;
  vec4 uvOrigin;
  vec4 uvAxes;
  vec4 overlayInfo;
};
float sourcePixelOnAxis(
  float point,
  float targetSize,
  float sourceSize,
  float firstInset,
  float lastInset
) {
  float firstSource = clamp(firstInset, 0.0, sourceSize);
  float lastSource = clamp(lastInset, 0.0, sourceSize - firstSource);
  float sourceCenter = max(0.0, sourceSize - firstSource - lastSource);
  float edgeScale = min(1.0, targetSize / max(firstSource + lastSource, 0.000001));
  float firstDisplay = firstSource * edgeScale;
  float lastDisplay = lastSource * edgeScale;
  float displayCenter = max(0.0, targetSize - firstDisplay - lastDisplay);
  if (point < firstDisplay && firstDisplay > 0.0) {
    return point * firstSource / firstDisplay;
  }
  if (point >= targetSize - lastDisplay && lastDisplay > 0.0) {
    return sourceSize - lastSource +
      (point - (targetSize - lastDisplay)) * lastSource / lastDisplay;
  }
  if (displayCenter > 0.000001) {
    return firstSource + (point - firstDisplay) * sourceCenter / displayCenter;
  }
  return firstSource;
}
float sampleLocalAlpha(vec2 point) {
  vec2 targetSize = max(targetInfo.xy, vec2(0.000001));
  vec2 sourceSize = max(sourceInfo.xy, vec2(1.0));
  float inside =
    step(0.0, point.x) * step(point.x, targetSize.x) *
    step(0.0, point.y) * step(point.y, targetSize.y);
  vec2 safePoint = clamp(point, vec2(0.0), targetSize);
  vec2 sourcePixel = vec2(
    sourcePixelOnAxis(safePoint.x, targetSize.x, sourceSize.x, sliceInsets.x, sliceInsets.y),
    sourcePixelOnAxis(safePoint.y, targetSize.y, sourceSize.y, sliceInsets.z, sliceInsets.w)
  );
  vec2 halfTexel = 0.5 / sourceSize;
  vec2 sourceUV = clamp(sourcePixel / sourceSize, halfTexel, vec2(1.0) - halfTexel);
  vec2 textureUV = uvOrigin.xy + uvAxes.xy * sourceUV.x + uvAxes.zw * sourceUV.y;
  return CCSampleWithAlphaSeparated(cc_spriteTexture, textureUV).a * inside;
}
float contourAlpha(vec2 point) {
  float smoothing = clamp(sourceInfo.z, 0.0, 2.0);
  if (smoothing <= 0.0) {
    return sampleLocalAlpha(point);
  }
  vec2 h = vec2(0.5 * smoothing);
  return 0.25 * (
    sampleLocalAlpha(point + vec2(-h.x, -h.y)) +
    sampleLocalAlpha(point + vec2( h.x, -h.y)) +
    sampleLocalAlpha(point + vec2(-h.x,  h.y)) +
    sampleLocalAlpha(point + vec2( h.x,  h.y))
  );
}
float alphaDerivative(float value) {
    return fwidth(value);
}
float alphaCoverage(float alpha, float derivative, float cutoff, float aaStrength) {
  float halfAA = max(0.5 * aaStrength * derivative, 0.00001);
  return smoothstep(
    max(0.0, cutoff - halfAA),
    min(1.0, cutoff + halfAA),
    alpha
  );
}
float outsideStrokeCoverage(float outerCoverage, float sourceAlpha) {
  return clamp(outerCoverage, 0.0, 1.0) * (1.0 - clamp(sourceAlpha, 0.0, 1.0));
}
vec4 frag () {
  vec2 localPoint = vec2(v_uv.x, 1.0 - v_uv.y) * overlayInfo.xy -
    (overlayInfo.xy - targetInfo.xy) * 0.5;
  float width = clamp(targetInfo.z, 0.0, 16.0);
  float cutoff = clamp(targetInfo.w, 0.001, 0.98);
  float aaStrength = clamp(sourceInfo.w, 0.5, 2.0);
  float alignment = clamp(floor(overlayInfo.w + 0.5), 0.0, 2.0);
  float innerRadius = alignment < 0.5 ? width : (alignment < 1.5 ? width * 0.5 : 0.0);
  float outerRadius = alignment > 1.5 ? width : (alignment > 0.5 ? width * 0.5 : 0.0);
  float rawAlpha = sampleLocalAlpha(localPoint);
  float shapeAlpha = contourAlpha(localPoint);
  float erodedAlpha = shapeAlpha;
  float dilatedAlpha = shapeAlpha;
  for (int y = -4; y <= 4; y++) {
    for (int x = -4; x <= 4; x++) {
      if (x != 0 || y != 0) {
        vec2 p = vec2(float(x), float(y)) / 4.0;
        p /= max(1.0, length(p));
        if (innerRadius > 0.0) {
          erodedAlpha = min(erodedAlpha, contourAlpha(localPoint + p * innerRadius));
        }
        if (outerRadius > 0.0) {
          dilatedAlpha = max(dilatedAlpha, contourAlpha(localPoint + p * outerRadius));
        }
      }
    }
  }
  float shapeDerivative = alphaDerivative(shapeAlpha);
  float erodedDerivative = alphaDerivative(erodedAlpha);
  float dilatedDerivative = alphaDerivative(dilatedAlpha);
  float shapeCoverage = alphaCoverage(shapeAlpha, shapeDerivative, cutoff, aaStrength);
  float erodedCoverage = alphaCoverage(erodedAlpha, erodedDerivative, cutoff, aaStrength);
  float dilatedCoverage = alphaCoverage(dilatedAlpha, dilatedDerivative, cutoff, aaStrength);
  float innerCoverage = innerRadius > 0.0 ? erodedCoverage : shapeCoverage;
  float outerCoverage = outerRadius > 0.0 ? dilatedCoverage : shapeCoverage;
  float strokeCoverage = clamp(outerCoverage - innerCoverage, 0.0, 1.0);
  if (alignment < 0.5) {
    vec2 targetSize = max(targetInfo.xy, vec2(0.000001));
    float insideTarget =
      step(0.0, localPoint.x) * step(localPoint.x, targetSize.x) *
      step(0.0, localPoint.y) * step(localPoint.y, targetSize.y);
    strokeCoverage *= insideTarget;
  }
  float sourceStrength = clamp(rawAlpha, 0.0, 1.0);
  float hasSource = rawAlpha > 0.0 ? 1.0 : 0.0;
  float preservedStrength;
  if (alignment < 0.5) {
    preservedStrength = sourceStrength;
  } else if (alignment < 1.5) {
    preservedStrength = mix(1.0, sourceStrength, hasSource);
  } else {
    preservedStrength = rawAlpha > 0.000001 ? 0.0 : 1.0;
  }
  bool repairCorner = false;
  if (alignment > 1.5 && uvOrigin.z > 0.5) {
    vec2 edgePoint = clamp(localPoint, vec2(0.0), max(targetInfo.xy, vec2(0.000001)));
    repairCorner = sampleLocalAlpha(edgePoint) < 0.999999;
  }
  if (repairCorner) {
    strokeCoverage = outsideStrokeCoverage(outerCoverage, rawAlpha);
  } else {
    strokeCoverage *= mix(1.0, preservedStrength, step(0.5, overlayInfo.z));
  }
  float borderAlpha = strokeCoverage * clamp(borderColor.a, 0.0, 1.0);
  borderAlpha *= step(0.00001, width);
  return vec4(borderColor.rgb, borderAlpha) * v_color;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

